PRAGMA foreign_keys=ON;
CREATE TABLE families(id TEXT PRIMARY KEY,name TEXT NOT NULL,currency TEXT NOT NULL DEFAULT 'MXN',timezone TEXT NOT NULL DEFAULT 'America/Mazatlan',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE users(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,name TEXT NOT NULL,login TEXT NOT NULL COLLATE NOCASE,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,password_iterations INTEGER NOT NULL DEFAULT 310000,role TEXT NOT NULL CHECK(role IN('Owner','Admin','Adult','Member')),simple_mode INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(family_id,login));
CREATE TABLE sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash TEXT NOT NULL UNIQUE,csrf_hash TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,last_seen_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE login_attempts(id INTEGER PRIMARY KEY AUTOINCREMENT,login TEXT NOT NULL,ip_hash TEXT NOT NULL,success INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE family_members(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id) ON DELETE SET NULL,name TEXT NOT NULL,relation TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,name TEXT NOT NULL,type TEXT NOT NULL DEFAULT 'expense',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(family_id,name,type));
CREATE TABLE accounts(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,name TEXT NOT NULL,type TEXT NOT NULL,balance_cents INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE expenses(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,amount_cents INTEGER NOT NULL CHECK(amount_cents>=0),description TEXT NOT NULL,category_id TEXT REFERENCES categories(id),paid_by_member_id TEXT REFERENCES family_members(id),account_id TEXT REFERENCES accounts(id),scope TEXT NOT NULL DEFAULT 'family',date TEXT NOT NULL,notes TEXT,receipt_document_id TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE expense_splits(id TEXT PRIMARY KEY,expense_id TEXT NOT NULL REFERENCES expenses(id) ON DELETE CASCADE,member_id TEXT NOT NULL REFERENCES family_members(id),amount_cents INTEGER NOT NULL CHECK(amount_cents>=0));
CREATE TABLE incomes(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,amount_cents INTEGER NOT NULL,source TEXT NOT NULL,member_id TEXT REFERENCES family_members(id),date TEXT NOT NULL,notes TEXT,recurrence TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE budgets(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,month TEXT NOT NULL,amount_cents INTEGER NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(family_id,month));
CREATE TABLE budget_categories(id TEXT PRIMARY KEY,budget_id TEXT NOT NULL REFERENCES budgets(id) ON DELETE CASCADE,category_id TEXT NOT NULL REFERENCES categories(id),amount_cents INTEGER NOT NULL,UNIQUE(budget_id,category_id));
CREATE TABLE recurring_bills(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,name TEXT NOT NULL,amount_cents INTEGER,variable INTEGER NOT NULL DEFAULT 0,next_due_date TEXT NOT NULL,frequency TEXT NOT NULL,responsible_member_id TEXT REFERENCES family_members(id),category_id TEXT REFERENCES categories(id),notes TEXT,active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE bill_payments(id TEXT PRIMARY KEY,bill_id TEXT NOT NULL REFERENCES recurring_bills(id) ON DELETE CASCADE,paid_at TEXT NOT NULL,amount_cents INTEGER NOT NULL,expense_id TEXT REFERENCES expenses(id),created_by TEXT NOT NULL REFERENCES users(id));
CREATE TABLE subscriptions(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,service TEXT NOT NULL,cost_cents INTEGER NOT NULL,next_date TEXT NOT NULL,frequency TEXT NOT NULL,responsible_member_id TEXT REFERENCES family_members(id),active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE goals(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,name TEXT NOT NULL,target_cents INTEGER NOT NULL,current_cents INTEGER NOT NULL DEFAULT 0,target_date TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE goal_contributions(id TEXT PRIMARY KEY,goal_id TEXT NOT NULL REFERENCES goals(id) ON DELETE CASCADE,amount_cents INTEGER NOT NULL,date TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES users(id));
CREATE TABLE debts(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,from_member_id TEXT NOT NULL REFERENCES family_members(id),to_member_id TEXT NOT NULL REFERENCES family_members(id),amount_cents INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'open',expense_id TEXT REFERENCES expenses(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,settled_at TEXT);
CREATE TABLE shopping_items(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,name TEXT NOT NULL,quantity TEXT,category TEXT,added_by TEXT NOT NULL REFERENCES users(id),notes TEXT,completed INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TEXT);
CREATE TABLE tasks(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,name TEXT NOT NULL,responsible_member_id TEXT REFERENCES family_members(id),due_date TEXT,priority TEXT NOT NULL DEFAULT 'normal',recurrence TEXT,completed INTEGER NOT NULL DEFAULT 0,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE events(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,title TEXT NOT NULL,type TEXT NOT NULL,start_at TEXT NOT NULL,end_at TEXT,notes TEXT,created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE documents(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,name TEXT NOT NULL,kind TEXT NOT NULL,mime_type TEXT NOT NULL,size_bytes INTEGER NOT NULL,r2_key TEXT NOT NULL UNIQUE,uploaded_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id) ON DELETE CASCADE,type TEXT NOT NULL,title TEXT NOT NULL,body TEXT NOT NULL,read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ai_conversations(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE ai_messages(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES ai_conversations(id) ON DELETE CASCADE,role TEXT NOT NULL,content TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,key TEXT NOT NULL,value TEXT NOT NULL,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(family_id,key));
CREATE TABLE audit_log(id TEXT PRIMARY KEY,family_id TEXT NOT NULL REFERENCES families(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id),action TEXT NOT NULL,entity_type TEXT,entity_id TEXT,metadata TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_users_family ON users(family_id);CREATE INDEX idx_expenses_family_date ON expenses(family_id,date);CREATE INDEX idx_incomes_family_date ON incomes(family_id,date);CREATE INDEX idx_bills_family_due ON recurring_bills(family_id,next_due_date);CREATE INDEX idx_tasks_family_due ON tasks(family_id,due_date);CREATE INDEX idx_events_family_start ON events(family_id,start_at);CREATE INDEX idx_docs_family ON documents(family_id);CREATE INDEX idx_audit_family_date ON audit_log(family_id,created_at);CREATE INDEX idx_login_attempts ON login_attempts(login,created_at);
